fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    let n = indices.len();

    // Pre-allocate a result vector of the same length as indices
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        let row = indices[i] as usize;  // convert index to usize for indexing
        // Each row in choices has length == n by problem statement
        let value = choices[row][i];
        result.push(value);
    }

    result
}